    newMap = UnmodifiableArrayBackedMap.getMap(originalMap.getBackingArray());
    assertEquals(originalMap, newMap);
    originalMap = UnmodifiableArrayBackedMap.EMPTY_MAP.copyAndPutAll(getTestParameters()).copyAndRemove("1");
