    assertTrue(Level.TRACE.isLessSpecificThan(Level.DEBUG));
    assertTrue(Level.TRACE.isLessSpecificThan(Level.TRACE));
    assertFalse(Level.TRACE.isLessSpecificThan(Level.ALL));
