    map.put("bytes", new byte[] { 1, 2 });
    map.put("shorts", new short[] { 3, 4 });
    map.put("ints", new int[] { 256, 257 });
    map.put("longs", new long[] { 2147483648L, 2147483649L });
    map.put("floats", new float[] { 1.0F, 1.1F });
    map.put("doubles", new double[] { 2.0D, 2.1D });
    map.put("objects", new Object[] { "foo", "bar" });
    final String actualJson = new ObjectMapMessage().with("key1", "val1").with("key2", Collections.singletonMap("key2.1", "val2.1")).with("key3", Arrays.asList(3, (byte) 127, 4.5D, 4.6F, Arrays.asList(true, false), new BigDecimal(30), Collections.singletonMap("key3.3", "val3.3"))).with("key4", map).getFormattedMessage(new String[] { "JSON" });
    final String expectedJson = ("{" + "'key1':'val1'," + "'key2':{'key2.1':'val2.1'}," + "'key3':[3,127,4.5,4.6,[true,false],30,{'key3.3':'val3.3'}]," + "'key4':{" + "'chars':['a','b','c']," + "'booleans':[true,false]," + "'bytes':[1,2]," + "'shorts':[3,4]," + "'ints':[256,257]," + "'longs':[2147483648,2147483649]," + "'floats':[1.0,1.1]," + "'doubles':[2.0,2.1]," + "'objects':['foo','bar']" + "}}").replace('\'', '"');
    assertEquals(expectedJson, actualJson);
}

