/**
 * Testing synchronization in the getLoggersInContext() method
 */
@Test
synchronized void testGetLoggersInContextSynch() throws Exception {
    final TestLoggerAdapter adapter = new TestLoggerAdapter();
    final int num = 500;
    final CountDownLatch startSignal = new CountDownLatch(1);
    final CountDownLatch doneSignal = new CountDownLatch(num);
    final RunnableThreadTest[] instances = new RunnableThreadTest[num];
    LoggerContext lastUsedContext = null;
    for (int i = 0; i < num; i++) {
        if (i % 2 == 0) {
            // every other time create a new context
            lastUsedContext = new SimpleLoggerContext();
        }
        final RunnableThreadTest runnable = new RunnableThreadTest(i, adapter, lastUsedContext, startSignal, doneSignal);
        final Thread thread = new Thread(runnable);
        thread.start();
        instances[i] = runnable;
    }
    startSignal.countDown();
    doneSignal.await();
    for (int i = 0; i < num; i = i + 2) {
        // maps for the same context should be the same instance
        final Map<String, Logger> resultMap1 = instances[i].getResultMap();
        final Map<String, Logger> resultMap2 = instances[i + 1].getResultMap();
        assertSame(resultMap1, resultMap2, "not the same map for instances" + i + " and " + (i + 1) + ":");
        assertEquals(2, resultMap1.size());
    }
}

/**
 * @see <a href="https://github.com/apache/logging-log4j2/issues/3143>Issue #3143</a>
 */
@ParameterizedTest
@MethodSource
void doesNotLoseLoggerReferences(@Nullable MessageFactory messageFactory) {
    LoggerRegistry<TestLogger> loggerRegistry = new LoggerRegistry<>();
    TestLogger logger = new TestLogger(LOGGER_NAME, messageFactory);
    WeakReference<TestLogger> loggerRef = new WeakReference<>(logger);
    // Register logger
    loggerRegistry.putIfAbsent(LOGGER_NAME, messageFactory, logger);
    // The JIT compiler/optimizer might figure out by himself the `logger` and `messageFactory` are no longer used:
    //   https://shipilev.net/jvm/anatomy-quarks/8-local-var-reachability/
    // We help him with the task though.
    logger = null;
    // Trigger a GC run
    System.gc();
    // Check if the logger is still there
    assertThat(loggerRef.get()).isNotNull();
    assertThat(loggerRegistry.getLogger(LOGGER_NAME, messageFactory)).isInstanceOf(TestLogger.class);
}

