    final List<Service> services = new ArrayList<>();
    assertDoesNotThrow(() -> ServiceLoaderUtil.safeStream(Service.class, ServiceLoader.load(Service.class, getClass().getClassLoader()), LOGGER).forEach(services::add));
    assertEquals(2, services.size());
    // A warning for each broken service
    final List<Throwable> errors = listener.findStatusData(Level.WARN).map(StatusData::getThrowable).collect(Collectors.toList());
    assertThat(errors.stream().map(Throwable::getMessage)).allMatch(message -> message.endsWith("invalid.Service not found") || message.endsWith("org.apache.logging.log4j.Logger not a subtype") || message.endsWith("Truncated class file"));
