@Test
void testColumnMapping() throws URISyntaxException {
    final URL configLocation = JdbcAppenderColumnMappingPropertiesTest.class.getResource("JdbcAppenderColumnMappingPropertiesTest.properties");
    assertThat(configLocation).isNotNull();
    final Configuration config = PropertiesConfigurationFactory.getInstance().getConfiguration(null, null, configLocation.toURI());
    assertThat(config).isNotNull();
    config.initialize();
    final Appender appender = config.getAppender("Jdbc");
    assertThat(appender).isInstanceOf(JdbcAppender.class);
    final JdbcAppender jdbcAppender = (JdbcAppender) appender;
    final ColumnMapping expected = ColumnMapping.newBuilder().setName("timestamp").setColumnType(Date.class).build();
    final ColumnMapping[] mappings = jdbcAppender.getManager().factoryData.columnMappings;
    assertThat(mappings).hasSize(1);
    assertThat(mappings[0]).isEqualTo(expected);
}

