/**
 * Tests whether a missing name or file name causes the builder to return
 * {@code null}.
 */
@Test
void testConstraints() {
    final AtomicInteger counter = new AtomicInteger();
    final StatusListener listener = new StatusListener() {

        @Override
        public void close() {
        }

        @Override
        public void log(final StatusData data) {
            counter.incrementAndGet();
        }

        @Override
        public Level getStatusLevel() {
            return Level.ERROR;
        }
    };
    try {
        StatusLogger.getLogger().registerListener(listener);
        FileAppender appender = FileAppender.newBuilder().build();
        assertNull(appender);
        assertTrue(counter.getAndSet(0) > 0);
        appender = FileAppender.newBuilder().setFileName("target/FileAppenderBuilderTest.log").build();
        assertNull(appender);
        assertTrue(counter.getAndSet(0) > 0);
        appender = FileAppender.newBuilder().setName("FILE").build();
        assertNull(appender);
        assertTrue(counter.getAndSet(0) > 0);
        appender = FileAppender.newBuilder().setName("FILE").setFileName("target/FileAppenderBuilderTest.log").build();
        assertNotNull(appender);
        assertEquals(0, counter.get());
    } catch (NullPointerException e) {
        // thrown if no filename is provided
        fail(e);
    } finally {
        StatusLogger.getLogger().removeListener(listener);
    }
}

@ParameterizedTest
@CsvSource({ "rwxrwxrwx,true,2", "rw-r--r--,false,3", "rw-------,true,4", "rw-rw----,false,5" })
void testFilePermissionsAPI(final String filePermissions, final boolean createOnDemand, final int fileIndex) throws Exception {
    final File file = new File(DIR, "AppenderTest-" + fileIndex + ".log");
    final Path path = file.toPath();
    final Layout<String> layout = PatternLayout.newBuilder().setPattern(PatternLayout.SIMPLE_CONVERSION_PATTERN).build();
    // @formatter:off
    final FileAppender appender = FileAppender.newBuilder().setFileName(file.getAbsolutePath()).setName("test").setImmediateFlush(false).setIgnoreExceptions(false).setBufferedIo(false).setBufferSize(1).setLayout(layout).setCreateOnDemand(createOnDemand).setFilePermissions(filePermissions).build();
    // @formatter:on
    try {
        appender.start();
        assertTrue(appender.isStarted(), "Appender did not start");
        assertNotEquals(createOnDemand, Files.exists(path));
        long curLen = file.length();
        long prevLen = curLen;
        assertEquals(0, curLen, "File length: " + curLen);
        for (int i = 0; i < 100; ++i) {
            final LogEvent event = Log4jLogEvent.newBuilder().setLoggerName(//
            "TestLogger").setLoggerFqcn(FileAppenderPermissionsTest.class.getName()).setLevel(//
            Level.INFO).setMessage(new SimpleMessage("Test")).setThreadName(//
            this.getClass().getSimpleName()).setTimeMillis(System.currentTimeMillis()).build();
            try {
                appender.append(event);
                curLen = file.length();
                assertTrue(curLen > prevLen, "File length: " + curLen);
                // Give up control long enough for another thread/process to occasionally do something.
                Thread.sleep(25);
            } catch (final Exception ex) {
                throw ex;
            }
            prevLen = curLen;
        }
        assertEquals(filePermissions, PosixFilePermissions.toString(Files.getPosixFilePermissions(path)));
    } finally {
        appender.stop();
    }
    assertFalse(appender.isStarted(), "Appender did not stop");
}

