    assertTrue(original.containsKey("B"), "B");
    assertTrue(original.containsKey("3"), "3");
    assertFalse(original.containsKey("A"), "A");
    original.putValue("A", "AAA");
    assertTrue(original.containsKey("a"), "a");
    assertTrue(original.containsKey("B"), "B");
    assertTrue(original.containsKey("3"), "3");
    assertTrue(original.containsKey("A"), "A");
}

