@EnumSource(NamedInstantPattern.class)
void compatibilityOfLegacyPattern(NamedInstantPattern namedPattern) {
    if (namedPattern == NamedInstantPattern.ISO8601_OFFSET_DATE_TIME_HH) {
        ZoneOffset offset = ZoneId.systemDefault().getRules().getOffset(Instant.now());
        assumeThat(offset.getTotalSeconds() % 3600 == 0).withFailMessage("Skipping test: ISO8601_OFFSET_DATE_TIME_HH requires a whole-hour offset, but system offset is %s", offset).isTrue();
    }
    InstantPatternFormatter legacyFormatter = InstantPatternFormatter.newBuilder().setPattern(namedPattern.getLegacyPattern()).setLegacyFormattersEnabled(true).build();
    InstantPatternFormatter formatter = InstantPatternFormatter.newBuilder().setPattern(namedPattern.getPattern()).setLegacyFormattersEnabled(false).build();
    Instant javaTimeInstant = Instant.now();
    MutableInstant instant = new MutableInstant();
    instant.initFromEpochSecond(javaTimeInstant.getEpochSecond(), javaTimeInstant.getNano());
    String legacy = legacyFormatter.format(instant);
    String modern = formatter.format(instant);
    assertThat(legacy).isEqualTo(modern);
}

