@Test
void testExpungeStaleWeakReferenceEntries() {
    final String loggerNamePrefix = "testLogger_";
    final int numberOfLoggers = 1000;
    for (int i = 0; i < numberOfLoggers; i++) {
        final Logger logger = registry.computeIfAbsent(loggerNamePrefix + i, messageFactory, (name, factory) -> new Logger(loggerContext, name, factory) {
        });
        logger.info("Using logger {}", logger.getName());
    }
    await().atMost(10, SECONDS).pollInterval(100, MILLISECONDS).untilAsserted(() -> {
        System.gc();
        registry.computeIfAbsent("triggerExpunge", messageFactory, (name, factory) -> new Logger(loggerContext, name, factory) {
        });
        final Map<MessageFactory, Map<String, WeakReference<Logger>>> loggerRefByNameByMessageFactory = reflectAndGetLoggerMapFromRegistry();
        final Map<String, WeakReference<Logger>> loggerRefByName = loggerRefByNameByMessageFactory.get(messageFactory);
        int unexpectedCount = 0;
        for (int i = 0; i < numberOfLoggers; i++) {
            if (loggerRefByName.containsKey(loggerNamePrefix + i)) {
                unexpectedCount++;
            }
        }
        assertEquals(0, unexpectedCount, "Found " + unexpectedCount + " unexpected stale entries for MessageFactory");
    });
}

