@Test
void test1SimpleLoggings1Jul() {
    julLog.info("Test-'Info'-Log with JUL");
    julLog.fine("Test-'Fine'-Log with JUL");
    // should not be logged because JUL-level is FINER
    julLog.finest("Test-'Finest'-Log with JUL");
    // thus add another log afterwards to allow checking
    julLog.warning("Test-'Warn'-Log with JUL");
    final String methodRE = "SimpleLoggings1Jul";
    assertSysoutMatches(log4j(org.apache.logging.log4j.Level.INFO, true, methodRE, "'Info'-Log with JUL", null) + jul(java.util.logging.Level.INFO, methodRE, "'Info'-Log with JUL", null) + log4j(org.apache.logging.log4j.Level.DEBUG, true, methodRE, "'Fine'-Log with JUL", null) + jul(java.util.logging.Level.FINE, methodRE, "'Fine'-Log with JUL", null) + // no finest/trace
    log4j(org.apache.logging.log4j.Level.WARN, true, methodRE, "'Warn'-Log with JUL", null) + jul(java.util.logging.Level.WARNING, methodRE, "'Warn'-Log with JUL", null));
}

