@Test
void test5LevelPropGC() {
    // this test will fail if you comment out "julLoggerRefs.add(julLog);" in propagateLogLevels()
    // at start, all should be fine
    test5LevelPropFromConfigFile();
    final java.util.logging.Logger julLogRef = java.util.logging.Logger.getLogger("log4j.Log4jBridgeHandlerTest.propagate1.nested1");
    // a single call is sufficient
    System.gc();
    System.out.println("sysout:  test5LevelPropGC() still has reference to JUL-logger: " + julLogRef.getName() + " / " + julLogRef);
    try {
        // even after GC the not referenced loggers should still be there
        test5LevelPropFromConfigFile();
    } catch (Throwable t) {
        debugPrintJulLoggers("After GC");
        // => JUL root logger, above explicitly referenced logger and its parent ("...propagate1")
        //    and the global referenced julLog ("...jul.Log4jBridgeHandlerTest") are still there, the
        //    others are null-references now
        throw t;
    }
}

