        // Check the raw parent exception.
        final String exPattern = EXCEPTION_REGEX_FLAGS + exception1Regex(false) + "\nCaused by: " + exception3Regex(false);
        assertThat(accessor.getString("ex")).matches(exPattern);
        // Check the matcher usage on parent exception.
        final String matchedExPattern = EXCEPTION_REGEX_FLAGS + exception1Regex(true) + "\nCaused by: " + exception3Regex(false);
        assertThat(accessor.getString("stringMatchedEx")).matches(matchedExPattern);
        assertThat(accessor.getString("regexMatchedEx")).matches(matchedExPattern);
        // Check the raw child exception.
        final String rootExPattern = EXCEPTION_REGEX_FLAGS + exception3Regex(false);
        assertThat(accessor.getString("rootEx")).matches(rootExPattern);
        // Check the matcher usage on child exception.
        final String matchedRootExPattern = EXCEPTION_REGEX_FLAGS + exception3Regex(true);
        assertThat(accessor.getString("stringMatchedRootEx")).matches(matchedRootExPattern);
        assertThat(accessor.getString("regexMatchedRootEx")).matches(matchedRootExPattern);
    });
}

@Test
void should_not_fail_on_truncated_output_not_ending_with_newline() {
    // Try to find an exception whose truncated stack trace does not end with a newline
    final int maxStringLength = 100;
    final float maxByteCountPerChar = JsonTemplateLayoutDefaults.getCharset().newEncoder().maxBytesPerChar();
    final int maxStringByteCount = Math.toIntExact(Math.round(Math.ceil(maxByteCountPerChar * maxStringLength)));
    final TruncatingBufferedPrintWriter writer = TruncatingBufferedPrintWriter.ofCapacity(maxStringByteCount);
    Exception exception;
    String message = "m";
    do {
        exception = new Exception(message);
        exception.printStackTrace(writer);
        if (writer.truncated() && writer.buffer()[writer.length() - 1] != '\n') {
            break;
        }
        writer.close();
        message += "m";
    } while (true);
    // Create the event template
    final String eventTemplate = writeJson(asMap("ex", asMap("$resolver", "exception", "field", "stackTrace", "stackTrace", asMap("stringified", asMap("truncation", asMap("suffix", TRUNCATION_SUFFIX, "pointMatcherStrings", singletonList("this string shouldn't match with anything")))))));
    // Create the layout
    final JsonTemplateLayout layout = JsonTemplateLayout.newBuilder().setConfiguration(CONFIGURATION).setEventTemplate(eventTemplate).setMaxStringLength(maxStringLength).setStackTraceEnabled(true).build();
    // Create the log event
    final LogEvent logEvent = Log4jLogEvent.newBuilder().setThrown(exception).build();
    // Check the serialized event
    usingSerializedLogEventAccessor(layout, logEvent, accessor -> {
        final int expectedStackTraceLength = maxStringLength + TRUNCATION_SUFFIX.length();
        final String stackTrace = accessor.getString("ex");
        assertThat(stackTrace).hasSizeLessThan(expectedStackTraceLength);
    });
}

